package com.tenora365.controller;import com.lowagie.text.*;import com.lowagie.text.pdf.*;import com.tenora365.entity.FeePayment;import com.tenora365.repository.FeePaymentRepository;import com.tenora365.tenant.TenantContext;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;import java.io.*;
@RestController @RequestMapping("/api/pdf") public class PdfController{final FeePaymentRepository fees;PdfController(FeePaymentRepository f){fees=f;}@GetMapping("/fee-receipt/{id}")ResponseEntity<byte[]> receipt(@PathVariable Long id)throws Exception{FeePayment f=fees.findByIdAndSchoolId(id,TenantContext.get()).orElseThrow();ByteArrayOutputStream out=new ByteArrayOutputStream();Document d=new Document();PdfWriter.getInstance(d,out);d.open();d.add(new Paragraph("TENORA365"));d.add(new Paragraph("FEE RECEIPT"));d.add(new Paragraph("Receipt: "+f.getReceiptNo()));d.add(new Paragraph("Amount: ₹"+f.getAmount()));d.add(new Paragraph("Fee Head: "+f.getFeeHead()));d.add(new Paragraph("Status: "+f.getStatus()));d.add(new Paragraph("Paid on: "+f.getPaidOn()));d.close();return ResponseEntity.ok().contentType(MediaType.APPLICATION_PDF).header(HttpHeaders.CONTENT_DISPOSITION,"attachment; filename="+f.getReceiptNo()+".pdf").body(out.toByteArray());}}
